//! Parity with the reference: the registry and engine tables, and the saved
//! state after loading every corpus preset, every preset-state test preset and
//! the init preset, compared byte for byte with what the reference writes
//! (`migration/corpus/preset_state`, generated by
//! `migration/scripts/preset_goldens.py` and checked against the pinned
//! reference in CI).

use std::path::{Path, PathBuf};

use sas_common::json::{self, Value};
use sas_preset::{engine, registry, Error, InitContent, PresetState, StringTable, WavetableState};

fn repo() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("../../..")
}

fn golden_dir() -> PathBuf {
    repo().join("migration/corpus/preset_state")
}

fn read_golden(name: &str) -> String {
    let path = golden_dir().join(name);
    std::fs::read_to_string(&path)
        .unwrap_or_else(|error| panic!("cannot read {}: {error}", path.display()))
}

fn golden_json(name: &str) -> Value {
    json::parse(&read_golden(name)).expect("golden parses")
}

fn reference_registry() -> Value {
    golden_json("registry.json")
}

/// The init content of the reference. The default wavetables are taken from
/// the reference's init state until `sas-wavetable` provides the wavetable
/// state model; everything else is generated by the port.
fn init_content() -> InitContent {
    let init = golden_json("init.json");
    let wavetables = init.get("settings").unwrap().get("wavetables").unwrap();
    let sample_seed = reference_registry()
        .get("init")
        .unwrap()
        .get("sample_seed")
        .unwrap()
        .to_i32()
        .unwrap();
    InitContent {
        wavetables: wavetables
            .iter_values()
            .map(|wavetable| WavetableState(wavetable.clone()))
            .collect(),
        sample_seed,
    }
}

/// The first place two JSON values differ, for readable failures.
fn first_difference(path: &str, expected: &Value, actual: &Value) -> Option<String> {
    match (expected, actual) {
        (Value::Object(a), Value::Object(b)) => {
            for key in a.keys().chain(b.keys()) {
                let (x, y) = (
                    a.get(key).unwrap_or(&Value::Null),
                    b.get(key).unwrap_or(&Value::Null),
                );
                if a.contains_key(key) != b.contains_key(key) {
                    return Some(format!(
                        "{path}/{key}: expected {}, got {}",
                        x.dump(),
                        y.dump()
                    ));
                }
                if let Some(difference) = first_difference(&format!("{path}/{key}"), x, y) {
                    return Some(difference);
                }
            }
            None
        }
        (Value::Array(a), Value::Array(b)) => {
            for i in 0..a.len().max(b.len()) {
                let (x, y) = (
                    a.get(i).unwrap_or(&Value::Null),
                    b.get(i).unwrap_or(&Value::Null),
                );
                if let Some(difference) = first_difference(&format!("{path}/{i}"), x, y) {
                    return Some(difference);
                }
            }
            None
        }
        _ if expected.dump() == actual.dump() => None,
        _ => {
            let (x, y) = (expected.dump(), actual.dump());
            let shorten = |text: String| {
                if text.len() > 120 {
                    format!("{}…", &text[..120])
                } else {
                    text
                }
            };
            Some(format!(
                "{path}: expected {}, got {}",
                shorten(x),
                shorten(y)
            ))
        }
    }
}

fn assert_same_state(label: &str, expected_text: &str, state: &PresetState) {
    let actual_text = state.to_json_string() + "\n";
    if actual_text == expected_text {
        return;
    }
    let expected = json::parse(expected_text).expect("golden parses");
    let difference = first_difference("", &expected, &state.to_json())
        .unwrap_or_else(|| "same values, different serialization".to_string());
    panic!("{label}: saved state differs from the reference at {difference}");
}

fn preset_paths() -> Vec<(String, PathBuf, bool)> {
    let mut presets = Vec::new();
    for (directory, corpus) in [("presets", true), ("preset_tests", false)] {
        let mut paths: Vec<PathBuf> =
            std::fs::read_dir(repo().join("migration/corpus").join(directory))
                .unwrap()
                .map(|entry| entry.unwrap().path())
                .filter(|path| {
                    path.extension()
                        .is_some_and(|extension| extension == "vital")
                })
                .collect();
        paths.sort();
        for path in paths {
            let name = path.file_stem().unwrap().to_string_lossy().to_string();
            presets.push((name, path, corpus));
        }
    }
    presets
}

#[test]
fn registry_matches_reference() {
    let reference = reference_registry();
    let parameters = reference.get("parameters").unwrap();
    let registry = registry();
    assert_eq!(
        reference.get("num_parameters").unwrap().to_i32().unwrap() as usize,
        registry.len()
    );
    assert_eq!(parameters.size(), registry.len());

    for (index, expected) in parameters.iter_values().enumerate() {
        let actual = registry.get_index(index).unwrap();
        let name = expected.get("name").unwrap().to_str().unwrap();
        assert_eq!(actual.name, name, "parameter {index}");
        let float = |key: &str| expected.get(key).unwrap().to_f32().unwrap();
        let text = |key: &str| expected.get(key).unwrap().to_str().unwrap().to_string();
        assert_eq!(
            actual.version_added,
            expected.get("version_added").unwrap().to_i32().unwrap(),
            "{name}"
        );
        assert_eq!(actual.min.to_bits(), float("min").to_bits(), "{name} min");
        assert_eq!(actual.max.to_bits(), float("max").to_bits(), "{name} max");
        assert_eq!(
            actual.default_value.to_bits(),
            float("default_value").to_bits(),
            "{name} default"
        );
        assert_eq!(
            actual.post_offset.to_bits(),
            float("post_offset").to_bits(),
            "{name} post_offset"
        );
        assert_eq!(
            actual.display_multiply.to_bits(),
            float("display_multiply").to_bits(),
            "{name} display_multiply"
        );
        assert_eq!(
            actual.value_scale.as_str(),
            text("value_scale"),
            "{name} value_scale"
        );
        assert_eq!(
            actual.display_invert,
            expected.get("display_invert").unwrap().to_bool().unwrap(),
            "{name}"
        );
        assert_eq!(
            actual.display_units,
            text("display_units"),
            "{name} display_units"
        );
        assert_eq!(
            actual.display_name,
            text("display_name"),
            "{name} display_name"
        );
        assert_eq!(
            actual.local_description,
            text("local_description"),
            "{name} local_description"
        );
        let table = expected.get("string_table").unwrap();
        let actual_table = actual.string_table.map(StringTable::upstream_name);
        assert_eq!(actual_table, table.to_str().ok(), "{name} string_table");
        assert_eq!(
            registry.get(name).map(|info| &info.name),
            Some(&actual.name)
        );
    }
}

#[test]
fn string_tables_match_reference() {
    let tables = reference_registry().get("string_tables").unwrap().clone();
    let Value::Object(tables) = tables else {
        panic!("string_tables is not an object")
    };
    assert_eq!(tables.len(), StringTable::ALL.len());
    for table in StringTable::ALL {
        let expected: Vec<&str> = tables[table.upstream_name()]
            .iter_values()
            .map(|value| value.to_str().unwrap())
            .collect();
        assert_eq!(
            table.values(),
            expected.as_slice(),
            "{}",
            table.upstream_name()
        );
    }
}

fn names(value: &Value) -> Vec<String> {
    value
        .iter_values()
        .map(|name| name.to_str().unwrap().to_string())
        .collect()
}

#[test]
fn engine_tables_match_reference() {
    let reference = reference_registry();
    assert_eq!(
        engine::controls(),
        names(reference.get("controls").unwrap())
    );
    assert_eq!(
        engine::modulation_sources(),
        names(reference.get("modulation_sources").unwrap())
    );
    assert_eq!(
        engine::modulation_destinations(),
        names(reference.get("mono_modulation_destinations").unwrap())
    );
    // SynthBase::isInvalidConnection never matches in this engine: no slot's
    // own processor owns a modulation destination, so the port has no such
    // rule. This keeps that assumption checked.
    for (slot, destinations) in reference
        .get("slot_self_destinations")
        .unwrap()
        .iter_values()
        .enumerate()
    {
        assert_eq!(destinations.size(), 0, "slot {slot} has self destinations");
    }
    assert_eq!(
        reference.get("synth_version").unwrap().to_str().unwrap(),
        sas_preset::version::SYNTH_VERSION
    );
    assert_eq!(
        reference
            .get("init")
            .unwrap()
            .get("random_generators_constructed")
            .unwrap()
            .to_i32()
            .unwrap(),
        1
    );
}

#[test]
fn init_state_matches_reference() {
    let state = PresetState::new(&init_content());
    assert_same_state("init", &read_golden("init.json"), &state);
}

/// Loads `path` on a fresh synth (the reference loads every preset on a newly
/// constructed `SynthBase`) and compares with `<name>.json`.
fn check_preset(name: &str, path: &Path) -> Option<PresetState> {
    let expected = read_golden(&format!("{name}.json"));
    let golden = json::parse(&expected).unwrap();
    let mut state = PresetState::new(&init_content());
    let result = state.load_file(path);

    if golden.count("load_error") != 0 {
        let message = golden.get("load_error").unwrap().to_str().unwrap();
        match (message, &result) {
            ("Preset was created with a newer version.", Err(Error::NewerVersion(_))) => {}
            ("Preset file is corrupted.", Err(Error::Corrupted(_))) => {}
            _ => panic!("{name}: reference fails with {message:?}, port gives {result:?}"),
        }
        return None;
    }
    if let Err(error) = result {
        panic!("{name}: reference loads it, port fails: {error}");
    }
    assert_same_state(name, &expected, &state);
    Some(state)
}

#[test]
fn every_preset_matches_reference() {
    let presets = preset_paths();
    assert!(presets.iter().filter(|(_, _, corpus)| *corpus).count() >= 5);
    let mut failures = Vec::new();
    for (name, path, _) in &presets {
        if let Err(panic) = std::panic::catch_unwind(|| check_preset(name, path)) {
            let message = panic
                .downcast_ref::<String>()
                .cloned()
                .or_else(|| panic.downcast_ref::<&str>().map(|text| text.to_string()))
                .unwrap_or_default();
            failures.push(message);
        }
    }
    assert!(
        failures.is_empty(),
        "{} of {} presets differ:\n{}",
        failures.len(),
        presets.len(),
        failures.join("\n")
    );
}

/// Saves `state` to a file named like the original and loads it again, as
/// `preset_goldens.py` does for the reference.
fn reload(name: &str, state: &PresetState) -> PresetState {
    let directory = std::env::temp_dir().join(format!(
        "sas-preset-roundtrip-{}-{name}",
        std::process::id()
    ));
    std::fs::create_dir_all(&directory).unwrap();
    let path = directory.join(format!("{name}.vital"));
    std::fs::write(&path, state.to_json_string()).unwrap();
    let mut reloaded = PresetState::new(&init_content());
    reloaded.load_file(&path).unwrap();
    std::fs::remove_dir_all(&directory).unwrap();
    reloaded
}

/// Load → save → load → save matches the reference doing the same, and
/// everything except the sample is a fixed point after the first save. The
/// sample is not: upstream saves it four frames late (its zero padding is
/// encoded), so every round trip delays it again.
#[test]
fn round_trips_match_reference_and_are_idempotent() {
    let init = init_content();
    let mut cases = vec![("init".to_string(), PresetState::new(&init))];
    for (name, path, corpus) in preset_paths() {
        if corpus {
            let mut state = PresetState::new(&init);
            state.load_file(&path).unwrap();
            cases.push((name, state));
        }
    }

    for (name, first) in cases {
        let second = reload(&name, &first);
        assert_same_state(
            &format!("{name} round trip"),
            &read_golden(&format!("{name}.roundtrip.json")),
            &second,
        );

        let mut once = first.to_json();
        let mut twice = second.to_json();
        let without_sample = |value: &mut Value| {
            let Value::Object(top) = value else {
                panic!("state is not an object")
            };
            let Some(Value::Object(settings)) = top.get_mut("settings") else {
                panic!("no settings")
            };
            settings.remove("sample");
            if name == "init" {
                // The init preset is unnamed; loading it from a file names it.
                top.remove("preset_name");
            }
        };
        without_sample(&mut once);
        without_sample(&mut twice);
        assert_eq!(
            once.dump(),
            twice.dump(),
            "{name}: second round trip changed more than the sample"
        );
    }
}
